"use strict";
/* Dependency-free bundler: wraps the CommonJS engine into dist/c10-sim.bundle.js (window.C10Sim) and writes dist/c10-sim-examples.js from tests golden fixtures.
   Usage: node modules/simulation/tools/build-bundle.js [--check]  (CI fails if dist is stale) */
const fs = require("fs"), path = require("path"); const root = path.join(__dirname, ".."); const files = [];
(function walk(d) { for (const f of fs.readdirSync(d).sort()) { const p = path.join(d, f); if (fs.statSync(p).isDirectory()) { if (["lib", "models"].includes(path.relative(root, p).split(path.sep)[0]) || p === root) { if (!["tools", "ui", "dist", "sql", "data"].includes(f)) walk(p); } } else if (f.endsWith(".js") && (d !== root || f === "index.js")) files.push(p); } })(root);
const rel = p => path.relative(root, p).split(path.sep).join("/"); let out = "/* C10-A025 simulation engine bundle — GENERATED by tools/build-bundle.js. DRAFT/ISOLATED. Do not edit. */\n(function (global) {\n\"use strict\";\nconst __defs = {}, __cache = {};\n";
for (const f of files) out += "__defs[" + JSON.stringify(rel(f)) + "] = function (module, exports, require) {\n" + fs.readFileSync(f, "utf8").replace(/^"use strict";\n?/, "") + "\n};\n";
out += `function __resolve(from, req) { const parts = from.split("/").slice(0, -1); for (const seg of req.split("/")) { if (seg === ".") continue; if (seg === "..") parts.pop(); else parts.push(seg); } let p = parts.join("/"); if (!p.endsWith(".js")) p += ".js"; return p; }
function __require(from) { return function (req) { if (!req.startsWith(".")) throw new Error("bundle: external module not allowed: " + req); const id = __resolve(from, req); if (!__defs[id]) throw new Error("bundle: missing " + id); if (__cache[id]) return __cache[id].exports; const m = { exports: {} }; __cache[id] = m; __defs[id](m, m.exports, __require(id)); return m.exports; }; }
global.C10Sim = __require("index.js")("./index.js");
})(typeof window !== "undefined" ? window : globalThis);\n`;
const golden = JSON.parse(fs.readFileSync(path.join(root, "../../tests/c10_a025/golden.json"), "utf8")); const ex = {}; for (const g of golden) ex[g.id] = { model: g.model, version: g.version, adverse: g.adverse, note: g.note, inputs: g.inputs };
const exOut = "/* GENERATED from tests/c10_a025/golden.json — synthetic examples only */\nwindow.C10SimExamples = " + JSON.stringify(ex) + ";\n";
const dist = path.join(root, "dist"); const a = path.join(dist, "c10-sim.bundle.js"), b = path.join(dist, "c10-sim-examples.js");
if (process.argv.includes("--check")) { for (const [f, c] of [[a, out], [b, exOut]]) if (!fs.existsSync(f) || fs.readFileSync(f, "utf8") !== c) { console.error("STALE: " + path.relative(root, f) + " — run node modules/simulation/tools/build-bundle.js"); process.exit(1); } console.log("bundle up to date (" + files.length + " modules)"); }
else { fs.mkdirSync(dist, { recursive: true }); fs.writeFileSync(a, out); fs.writeFileSync(b, exOut); console.log("built", rel(a), out.length + " bytes,", files.length, "modules"); }
